package com.zamcan.faceit.data

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import org.json.JSONObject
import java.io.File
import java.util.concurrent.ConcurrentHashMap

/**
 * The bundled curated pack: 100 wallpapers, object artwork and material tiles.
 *
 * Everything here is offline and read-only. The runtime index is generated by
 * `tools/generate_artwork.py` alongside the artwork itself, so the catalogue can
 * never drift from the files on disk.
 *
 * Resource discipline (AGENTS.md §7 and §13):
 *  - decoding happens off the main thread and is bounded by an explicit sample
 *    size computed from the target dimensions, never by decoding full size;
 *  - thumbnails are held in a small LRU cache that is cleared on memory pressure;
 *  - the full-resolution wallpaper is only decoded when it is actually applied.
 */
data class CuratedArtwork(
    val id: String,
    val title: String,
    val category: String,
    val asset: String,
    val thumbnail: String,
    val width: Int,
    val height: Int,
    val accent: Long
)

data class MaterialTexture(
    val id: String,
    val label: String,
    val asset: String
)

class CuratedLibrary(private val context: Context) {

    private val cache = object : LinkedHashMap<String, Bitmap>(24, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<String, Bitmap>?): Boolean =
            size > MAX_THUMBNAILS
    }

    @Volatile
    private var loaded: List<CuratedArtwork>? = null

    fun wallpapers(): List<CuratedArtwork> {
        loaded?.let { return it }
        synchronized(this) {
            loaded?.let { return it }
            val parsed = readIndex()
            loaded = parsed
            return parsed
        }
    }

    fun categories(): List<String> = wallpapers().map { it.category }.distinct()

    fun byCategory(category: String?): List<CuratedArtwork> =
        if (category == null) wallpapers() else wallpapers().filter { it.category == category }

    fun find(id: String?): CuratedArtwork? = wallpapers().firstOrNull { it.id == id }

    private fun readIndex(): List<CuratedArtwork> = runCatching {
        val raw = context.assets.open(INDEX_PATH).bufferedReader().use { it.readText() }
        val array = JSONObject(raw).getJSONArray("wallpapers")
        buildList {
            for (i in 0 until array.length()) {
                val item = array.getJSONObject(i)
                add(
                    CuratedArtwork(
                        id = item.getString("id"),
                        title = item.getString("title"),
                        category = item.getString("category"),
                        asset = item.getString("asset"),
                        thumbnail = item.getString("thumbnail"),
                        width = item.getInt("width"),
                        height = item.getInt("height"),
                        accent = item.optLong("accent", 0L)
                    )
                )
            }
        }
    }.getOrDefault(emptyList())

    /**
     * Decode a gallery thumbnail at (approximately) the display size.
     *
     * Call from a background dispatcher. The bitmap is cached, so scrolling a
     * grid does not re-decode, and the cache is bounded so it cannot grow without
     * limit on a low-memory device.
     */
    fun thumbnail(artwork: CuratedArtwork, targetWidthPx: Int): Bitmap? {
        val key = "${artwork.id}@$targetWidthPx"
        cache[key]?.let { if (!it.isRecycled) return it }
        val bitmap = decodeSampled(artwork.thumbnail, targetWidthPx) ?: return null
        synchronized(cache) { cache[key] = bitmap }
        return bitmap
    }

    /** Full-resolution decode for preview or wallpaper application. */
    fun fullSize(artwork: CuratedArtwork, targetWidthPx: Int = 1080): Bitmap? =
        decodeSampled(artwork.asset, targetWidthPx)

    fun texture(texture: MaterialTexture, targetWidthPx: Int = 512): Bitmap? =
        decodeSampled(texture.asset, targetWidthPx)

    fun objectArtwork(id: String, targetWidthPx: Int = 720): Bitmap? {
        val path = "objects/$id.png"
        return decodeSampled(path, targetWidthPx)
    }

    fun objectIds(): List<String> = OBJECT_IDS

    private fun decodeSampled(path: String, targetWidthPx: Int): Bitmap? = runCatching {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        context.assets.open(path).use { BitmapFactory.decodeStream(it, null, bounds) }
        if (bounds.outWidth <= 0) return null

        var sample = 1
        while (bounds.outWidth / (sample * 2) >= targetWidthPx.coerceAtLeast(1)) {
            sample *= 2
        }
        val options = BitmapFactory.Options().apply {
            inSampleSize = sample
            inPreferredConfig = Bitmap.Config.ARGB_8888
        }
        context.assets.open(path).use { BitmapFactory.decodeStream(it, null, options) }
    }.getOrNull()

    /** Release every cached bitmap. Called when the gallery leaves composition. */
    fun trimMemory() {
        synchronized(cache) {
            cache.values.forEach { if (!it.isRecycled) it.recycle() }
            cache.clear()
        }
    }

    companion object {
        private const val INDEX_PATH = "artwork_index.json"
        private const val MAX_THUMBNAILS = 48

        /** Object artwork shipped with the pack. */
        val OBJECT_IDS = listOf(
            "object-crystal", "object-sphere", "object-arch", "object-dome", "object-torus",
            "object-monolith", "object-prism", "object-cubes", "object-obelisk", "object-column"
        )

        /** Material tiles shipped with the pack, matched to the studio's finishes. */
        val TEXTURES = listOf(
            MaterialTexture("texture-marble", "Marble", "textures/texture-marble.png"),
            MaterialTexture("texture-travertine", "Travertine", "textures/texture-travertine.png"),
            MaterialTexture("texture-ceramic", "Glazed ceramic", "textures/texture-ceramic.png"),
            MaterialTexture("texture-stone", "Natural stone", "textures/texture-stone.png"),
            MaterialTexture("texture-brushed_metal", "Brushed metal", "textures/texture-brushed_metal.png"),
            MaterialTexture("texture-frosted_glass", "Frosted glass", "textures/texture-frosted_glass.png"),
            MaterialTexture("texture-basalt", "Basalt", "textures/texture-basalt.png"),
            MaterialTexture("texture-sandstone", "Sandstone", "textures/texture-sandstone.png")
        )

        /** Human label for an object id, e.g. "object-crystal" -> "Crystal". */
        fun objectLabel(id: String): String =
            id.removePrefix("object-")
                .split('-')
                .joinToString(" ") { part -> part.replaceFirstChar { it.uppercase() } }

        fun textureForFinish(finish: String): MaterialTexture? = TEXTURES.firstOrNull {
            it.label.equals(finish, ignoreCase = true) ||
                finish.contains(it.label.split(" ").last(), ignoreCase = true)
        }
    }
}

/** Small helper so the app can degrade cleanly if the index is missing. */
fun Context.curatedLibrary(): CuratedLibrary = CuratedLibrary(applicationContext)

